function pageFooterHtml() {
  return `
    <div class="letter-footer">
    </div>
  `;
}

function pageWrapper(innerHtml, isFirstPage) {
  const letterhead = isFirstPage ? `
    <div class="letterhead">
    <img class="logo-img" src="logonew.png" alt="Logo" />
    </div>
  ` : '';
  return `<div class="page">${letterhead}<div class="page-body">${innerHtml}</div>${pageFooterHtml()}</div>`;
}

